-- Section 10 risk warning contracts. Reuses existing alert tables; no new table.
UPDATE t_alert_rule SET version_status='RETIRED',is_enabled=0
WHERE rule_code IN ('SDK_VOLUME_ANOMALY','TABLE_CHANNEL_DATA_STALE','IMPORT_FAILURE_RATE_HIGH','MASKING_FAILURE_RATE_HIGH',
 'VERSION_MULTI_CHANNEL_ANOMALY','HIGH_RISK_CROSS_CHANNEL','NEGATIVE_SENTIMENT_SURGE','CONTENT_ERROR_SPIKE',
 'LONG_UNRESOLVED_JIRA','AI_CONSECUTIVE_FAILURE','MASKING_CONSECUTIVE_FAILURE') AND version_status='ACTIVE';


UPDATE t_alert_rule SET version_status='RETIRED',is_enabled=0 WHERE rule_code IN
 ('DEVICE_SAFETY_SUSPECTED','DEVICE_SAFETY_STRONG_EVIDENCE','SENSITIVE_DATA_RESIDUAL_BLOCKED','SENSITIVE_DATA_EXPOSURE_CONFIRMED') AND version_status='ACTIVE';

-- Code-shipped rules are implementation-approved; runtime still enforces contracts and on-call governance.
SELECT CONCAT('ALERT_RULE_CATALOG:',r.rule_code),'ALERT_RULE_CATALOG','risk-v1',
 JSON_OBJECT('ruleCode',r.rule_code,'implementationStatus','IMPLEMENTED','implementationEvidenceSha256',SHA2(CONCAT('risk-warning-v1:',r.rule_code),256),'builtIn',true),
 'alert-rule-catalog-v1','APPROVED','APPROVED',r.rule_code,1
FROM t_alert_rule r WHERE r.version='risk-v1'
ON DUPLICATE KEY UPDATE config_value=VALUES(config_value),lifecycle_status='APPROVED',approval_status='APPROVED',is_active=1;
